const i = (name, amount, unit, aliases = [], pantry = false) => ({ name, amount, unit, aliases, pantry });
const recipe = (value) => {
  const [country, course, protein] = META[value.id] || [value.cuisine, value.course || "основное", value.protein || "без мяса"];
  return { ...value, cuisine: country, flag: FLAGS[country] || "🌍", course, protein, source: OPEN_COOKBOOK };
};

